package jp.nw.controller;import java.io.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import jp.nw.entity.UserEntity;import jp.nw.model.ScheduleEventLogic;
@WebServlet("/ScheduleResponse") public class ScheduleResponseController extends HttpServlet{protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException{UserEntity u=(UserEntity)q.getSession().getAttribute("loginUser");try{new ScheduleEventLogic().respond(Long.parseLong(q.getParameter("eventId")),u.getUserId(),q.getParameter("status"));}catch(Exception e){q.getSession().setAttribute("scheduleFlash",e.getMessage());}s.sendRedirect(q.getContextPath()+"/OpenCalender");}}
